import {chromium} from 'playwright';
import {createServer} from 'node:http';
import {readFileSync,mkdirSync,writeFileSync} from 'node:fs';
import {resolve,dirname} from 'node:path';
import {fileURLToPath} from 'node:url';
import assert from 'node:assert/strict';
const root=resolve(dirname(fileURLToPath(import.meta.url)),'../../..');
const fixture=`
window.testState={actor:'synthetic-owner',mode:'normal',deleted:false,requests:[],refreshes:0,reauth:0};
const state=window.testState;
window.IIG_ACCOUNT_ACCESS={url:location.origin+'/fake-api',key:'synthetic-only'};
const groups=()=>[...(!state.deleted?[{group_pin:'6412',group_name:'Synthetic test group',admin_name:'Synthetic organiser'}]:[]),{group_pin:'6413',group_name:'Keep this group',admin_name:'Other organiser'}].map(g=>({...g,status:'active',plan_type:'complimentary',paid_status:'unpaid',admin_contact:'synthetic@example.test'}));
window.fetch=async()=>new Response('[]',{status:200});
window.IIGOwnerReads={create:()=>({load:async()=>({response:new Response(JSON.stringify(groups()),{status:200}),overview:{groups:groups(),total_groups:groups().length,has_more:false},details:new Map(groups().map(g=>[g.group_pin,{members:[{name:'Player '+g.group_pin}],history:[{title:'Round '+g.group_pin}],member_count:1,completed_round_count:1,current_round:null}]))})})};
window.syntheticApi={userId:()=>state.actor,reauth:()=>{state.reauth++;},refresh:async()=>{state.refreshes++;await window.fetch(location.origin+'/rest/v1/rpc/iig_list_registered_groups',{method:'POST',headers:{Authorization:'Bearer synthetic'},body:JSON.stringify({p_offset:0})});},request:async(path,body)=>{
 state.requests.push({path,body});
 if(path.endsWith('_review')){if(state.mode==='delayed')await new Promise(r=>state.resolveReview=r);return {group_id:'71001',group_pin:body.p_pin,group_name:state.mode==='xss'?'<img src=x onerror=alert(1)>':'Synthetic test group',fingerprint:'a'.repeat(64),can_delete:state.mode!=='blocked',blocked_reason:'This group has an Apple subscription record and cannot be deleted here.',needs_verification:state.mode==='stale',counts:{players:1,history_entries:1,past_trips:0}};}
 if(state.mode==='failure')throw Error('Connection failed');
 if(state.mode==='changed'){state.mode='normal';const error=Error('Group changed');error.code='40001';throw error;}
 if(state.mode==='pending')await new Promise(r=>state.resolveDelete=r);
 state.deleted=true;return {deleted:true,group_id:body.p_group_id,request_id:body.p_request_id};
}};
`;
let html=readFileSync(resolve(root,'app/owner-dashboard.html'),'utf8');
html=html.replace(/<script\b[^>]*>[\s\S]*?<\/script>/g,'');
html=html.replace('</body>',`<script>${fixture}</script><script src="owner-delete.js"></script><script src="owner-control.js"></script><script>window.iigOwnerCentre=IIGOwnerControl.mount();window.IIG_ACCOUNT_ACCESS.url=location.origin;document.getElementById('dashView').classList.remove('hidden');document.getElementById('loginView').classList.add('hidden');iigOwnerCentre.configureActions(syntheticApi);syntheticApi.refresh();</script></body>`);
if(process.argv.includes('--prepare')){const out=process.argv[process.argv.indexOf('--prepare')+1];mkdirSync(resolve(out,'app'),{recursive:true});writeFileSync(resolve(out,'app/owner-dashboard.html'),html);for(const file of ['owner-control.js','owner-delete.js','owner-control.css','icon-192.png'])writeFileSync(resolve(out,'app',file),readFileSync(resolve(root,'app',file)));process.exit(0);}
const server=createServer((req,res)=>{try{if(req.url==='/app/owner-dashboard.html'){res.setHeader('Content-Type','text/html');res.end(html);return;}const path=resolve(root,'.'+req.url.split('?')[0]);if(!path.startsWith(root+'/'))throw Error();res.setHeader('Content-Type',path.endsWith('.js')?'text/javascript':path.endsWith('.css')?'text/css':'application/octet-stream');res.end(readFileSync(path));}catch(_){res.statusCode=404;res.end();}});
await new Promise(r=>server.listen(0,'127.0.0.1',r));const origin='http://127.0.0.1:'+server.address().port;
const browser=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox']});
const page=await browser.newPage({viewport:{width:1280,height:900}});const errors=[];page.on('pageerror',e=>errors.push(e.message));
await page.route('**/*',route=>route.request().url().startsWith(origin)?route.continue():route.abort());
let passed=0;const test=async(name,fn)=>{await fn();passed++;console.log('PASS '+name);};
async function reset(mode='normal'){await page.goto(origin+'/app/owner-dashboard.html');await page.getByRole('button',{name:'Delete group permanently',exact:true}).waitFor();await page.evaluate(m=>testState.mode=m,mode);}
async function open(){await page.getByRole('button',{name:'Delete group permanently',exact:true}).click();await page.locator('#ownerDeleteStatus').waitFor();}
const button=()=>page.locator('#ownerDeleteSubmit');
const deletes=()=>page.evaluate(()=>testState.requests.filter(r=>r.path.endsWith('iig_owner_delete_group')));
try{
 await test('selected group has a deletion action and review makes no mutation',async()=>{await reset();await open();assert.equal(await button().isDisabled(),true);assert.equal((await deletes()).length,0);assert.match(await page.locator('#ownerDeleteGroup').innerText(),/6412/);});
 await test('wrong PIN stays disabled; cancel preserves the group',async()=>{await page.locator('#ownerDeleteConfirm').fill('DELETE 6413');assert.equal(await button().isDisabled(),true);await page.getByRole('button',{name:'Cancel',exact:true}).click();assert.equal((await deletes()).length,0);assert.equal(await page.locator('dialog').count(),0);});
 await test('confirmation sends exact group ID, PIN and review fingerprint; list clears',async()=>{await open();await page.locator('#ownerDeleteConfirm').fill('DELETE 6412');await button().click();await page.getByRole('heading',{name:'Group deleted',exact:true}).waitFor();const calls=await deletes();assert.equal(calls.length,1);assert.equal(calls[0].body.p_pin,'6412');assert.equal(calls[0].body.p_group_id,'71001');assert.equal(calls[0].body.p_fingerprint,'a'.repeat(64));assert.equal(await page.locator('[data-owner-group="6412"]').count(),0);assert.equal(await page.locator('[data-owner-group="6413"]').count()>0,true);await page.getByRole('button',{name:'Close',exact:true}).click();});
 await test('deletion refresh removes player and history rows',async()=>{await page.getByRole('button',{name:'All Players',exact:true}).click();assert.equal(await page.getByText('Player 6412',{exact:true}).count(),0);assert.equal(await page.getByText('Player 6413',{exact:true}).count(),1);await page.getByRole('button',{name:'History',exact:true}).click();assert.equal(await page.getByRole('heading',{name:'Round 6412',exact:true}).count(),0);assert.equal(await page.getByRole('heading',{name:'Round 6413',exact:true}).count(),1);});
 await test('stale email verification uses the existing sign-in adapter',async()=>{await reset('stale');await open();await page.getByRole('button',{name:'Email me a new code'}).click();assert.equal(await page.evaluate(()=>testState.reauth),1);assert.equal((await deletes()).length,0);assert.equal(await page.locator('dialog').count(),0);});
 await test('Apple subscription block cannot submit',async()=>{await reset('blocked');await open();assert.equal(await page.locator('#ownerDeleteForm').isHidden(),true);assert.match(await page.locator('#ownerDeleteStatus').innerText(),/Apple subscription/);assert.equal((await deletes()).length,0);});
 await test('stale review requires typing the confirmation again',async()=>{await reset('changed');await open();await page.locator('#ownerDeleteConfirm').fill('DELETE 6412');await button().click();await page.getByText('The group changed. Review its latest details and type the confirmation again.',{exact:true}).waitFor();assert.equal(await page.locator('#ownerDeleteConfirm').inputValue(),'');assert.equal(await button().isDisabled(),true);assert.equal((await deletes()).length,1);});
 await test('network retry reuses its idempotency key',async()=>{await reset('failure');await open();await page.locator('#ownerDeleteConfirm').fill('DELETE 6412');await button().click();await page.getByText(/retrying this same request is safe/).waitFor();await page.evaluate(()=>testState.mode='normal');await button().click();await page.getByRole('heading',{name:'Group deleted',exact:true}).waitFor();const calls=await deletes();assert.equal(calls.length,2);assert.equal(calls[0].body.p_request_id,calls[1].body.p_request_id);});
 await test('pending deletion prevents duplicate clicks and Escape',async()=>{await reset('pending');await open();await page.locator('#ownerDeleteConfirm').fill('DELETE 6412');await button().click();assert.equal(await button().isDisabled(),true);await page.keyboard.press('Escape');assert.equal(await page.locator('dialog[open]').count(),1);assert.equal((await deletes()).length,1);await page.evaluate(()=>testState.resolveDelete());await page.getByRole('heading',{name:'Group deleted',exact:true}).waitFor();});
 await test('account change closes the dialog and ignores late responses',async()=>{await reset('delayed');await open();await page.evaluate(()=>{testState.actor=null;iigOwnerCentre.closeActions();testState.resolveReview();});assert.equal(await page.locator('dialog').count(),0);assert.equal((await deletes()).length,0);});
 await test('group names rendered as text; mobile dialog fits',async()=>{await reset('xss');await page.setViewportSize({width:390,height:844});await open();assert.equal(await page.locator('#ownerDeleteGroup img').count(),0);assert.match(await page.locator('#ownerDeleteGroup').innerText(),/<img/);const rect=await page.locator('dialog').boundingBox();assert.ok(rect.x>=0&&rect.x+rect.width<=390);assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);mkdirSync(resolve(root,'.github/owner-delete/verification'),{recursive:true});await page.screenshot({path:resolve(root,'.github/owner-delete/verification/mobile-confirmation.png'),fullPage:true});});
 assert.deepEqual(errors,[]);console.log(JSON.stringify({passed,externalRequestsAllowed:false}));writeFileSync(resolve(root,'.github/owner-delete/verification/browser.json'),JSON.stringify({passed,errors,externalRequestsAllowed:false},null,2));
}finally{await browser.close();server.close();}
